import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
cuda_src = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
// CTA-level output/spatial tiling with shared-memory staging of the input tile,
// plus output-channel register blocking: each block computes OCB output channels
// for the same spatial tile so the staged input footprint and the per-voxel
// index arithmetic are amortized across OCB accumulators per thread.
// Optimization: widen the per-thread spatial register blocking along W so each
// thread computes WBF = TW/TWS = 4 output voxels (TW 16 -> 32) instead of 2.
// The inner accumulation loop is bound by shared-memory load throughput; with
// WBF accumulators the OCB weight broadcast loads per kernel tap and the
// per-tap index arithmetic are amortized across WBF FMAs, which roughly
// halves the number of shared-load instructions per FMA.
template <typename scalar_t, int OCB>
__global__ void __launch_bounds__(256) conv_transpose3d_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    int batch, int in_channels, int out_channels,
    int in_d, int in_h, int in_w,
    int out_d, int out_h, int out_w,
    int k_d, int k_h, int k_w,
    int s_d, int s_h, int s_w,
    int p_d, int p_h, int p_w,
    int groups, bool has_bias,
    int tiles_d, int tiles_h, int tiles_w)
{
    constexpr int TD = 4;
    constexpr int TH = 8;
    constexpr int TW = 32;
    constexpr int TWS = 8;
    constexpr int WBF = TW / TWS;
    extern __shared__ char smem_raw[];
    scalar_t* smem = reinterpret_cast<scalar_t*>(smem_raw);
    int oc_per_group = out_channels / groups;
    int ic_per_group = in_channels / groups;
    int chunks_per_group = (oc_per_group + OCB - 1) / OCB;
    int g = blockIdx.y / chunks_per_group;
    int chunk = blockIdx.y - g * chunks_per_group;
    int oc0_in_g = chunk * OCB;
    int oc_count = oc_per_group - oc0_in_g;
    if (oc_count > OCB) oc_count = OCB;
    int oc0 = g * oc_per_group + oc0_in_g;
    int ic_start = g * ic_per_group;
    long long tiles_per_batch = (long long)tiles_d * tiles_h * tiles_w;
    long long tile_lin = blockIdx.x;
    int n = (int)(tile_lin / tiles_per_batch);
    int rem = (int)(tile_lin % tiles_per_batch);
    int td0 = rem / (tiles_h * tiles_w);
    int rem2 = rem % (tiles_h * tiles_w);
    int th0 = rem2 / tiles_w;
    int tw0 = rem2 % tiles_w;
    int d0 = td0 * TD;
    int h0 = th0 * TH;
    int w0 = tw0 * TW;
    int tid = threadIdx.x;
    int td = tid / (TH * TWS);
    int th = (tid / TWS) % TH;
    int tw = tid % TWS;
    int d = d0 + td;
    int h = h0 + th;
    int w = w0 + tw;
    bool valid[WBF];
    #pragma unroll
    for (int i = 0; i < WBF; ++i) {
        valid[i] = (d < out_d) && (h < out_h) && (w + i * TWS < out_w);
    }
    auto floordiv = [](int a, int b) {
        return a >= 0 ? a / b : -((-a + b - 1) / b);
    };
    const bool unit_stride = (s_d == 1) && (s_h == 1) && (s_w == 1);
    int di0 = floordiv(d0 + p_d - (k_d - 1), s_d); if (di0 < 0) di0 = 0;
    int hi0 = floordiv(h0 + p_h - (k_h - 1), s_h); if (hi0 < 0) hi0 = 0;
    int wi0 = floordiv(w0 + p_w - (k_w - 1), s_w); if (wi0 < 0) wi0 = 0;
    int di1 = floordiv(d0 + TD - 1 + p_d, s_d); if (di1 > in_d - 1) di1 = in_d - 1;
    int hi1 = floordiv(h0 + TH - 1 + p_h, s_h); if (hi1 > in_h - 1) hi1 = in_h - 1;
    int wi1 = floordiv(w0 + TW - 1 + p_w, s_w); if (wi1 > in_w - 1) wi1 = in_w - 1;
    int ID = di1 - di0 + 1; if (ID < 1) ID = 1;
    int IH = hi1 - hi0 + 1; if (IH < 1) IH = 1;
    int IW = wi1 - wi0 + 1; if (IW < 1) IW = 1;
    int IWP = IW + 1;
    int tile_elems = ID * IH * IWP;
    int kvol = k_d * k_h * k_w;
    scalar_t* s_in[2];
    s_in[0] = smem;
    s_in[1] = smem + tile_elems + OCB * kvol;
    scalar_t* s_weight[2];
    s_weight[0] = smem + tile_elems;
    s_weight[1] = smem + 2 * tile_elems + OCB * kvol;
    scalar_t sum[WBF][OCB];
    #pragma unroll
    for (int i = 0; i < WBF; ++i) {
        #pragma unroll
        for (int j = 0; j < OCB; ++j) {
            scalar_t b = (scalar_t)0;
            if (has_bias && j < oc_count) b = bias[oc0 + j];
            sum[i][j] = b;
        }
    }
    long long in_hw = (long long)in_h * in_w;
    long long in_chw = (long long)in_d * in_hw;
    int ic_end = ic_start + ic_per_group;
    auto stage_tile = [&](int ic, int buf) {
        const scalar_t* in_ptr = input + ((long long)n * in_channels + ic) * in_chw;
        const scalar_t* w_ptr = weight + ((long long)ic * oc_per_group + oc0_in_g) * kvol;
        int wrows = oc_count * kvol;
        for (int e = tid; e < OCB * kvol; e += blockDim.x) {
            s_weight[buf][e] = (e < wrows) ? w_ptr[e] : (scalar_t)0;
        }
        for (int e = tid; e < tile_elems; e += blockDim.x) {
            int lw = e % IWP;
            int lh = (e / IWP) % IH;
            int ld = e / (IWP * IH);
            scalar_t v = (scalar_t)0;
            if (lw < IW) {
                int di = di0 + ld;
                int hi = hi0 + lh;
                int wi = wi0 + lw;
                if (di >= 0 && di < in_d && hi >= 0 && hi < in_h && wi >= 0 && wi < in_w) {
                    v = in_ptr[(long long)di * in_hw + (long long)hi * in_w + wi];
                }
            }
            s_in[buf][e] = v;
        }
    };
    stage_tile(ic_start, 0);
    __syncthreads();
    int buf = 0;
    for (int ic = ic_start; ic < ic_end; ++ic) {
        if (ic + 1 < ic_end) {
            stage_tile(ic + 1, buf ^ 1);
        }
        const scalar_t* cs_in = s_in[buf];
        const scalar_t* cs_weight = s_weight[buf];
        if (valid[0] || valid[1] || valid[2] || valid[3]) {
            if (unit_stride) {
                const int lw0 = w + p_w - wi0;
                for (int kz = 0; kz < k_d; ++kz) {
                    int ld = d + p_d - kz - di0;
                    if (ld < 0 || ld >= ID) continue;
                    for (int ky = 0; ky < k_h; ++ky) {
                        int lh = h + p_h - ky - hi0;
                        if (lh < 0 || lh >= IH) continue;
                        int base = (ld * IH + lh) * IWP;
                        int wbase = (kz * k_h + ky) * k_w;
                        for (int kx = 0; kx < k_w; ++kx) {
                            scalar_t a[WBF];
                            int lw = lw0 - kx;
                            #pragma unroll
                            for (int i = 0; i < WBF; ++i) {
                                a[i] = (scalar_t)0;
                                int lwi = lw + i * TWS;
                                if (valid[i] && lwi >= 0 && lwi < IW) {
                                    a[i] = cs_in[base + lwi];
                                }
                            }
                            #pragma unroll
                            for (int j = 0; j < OCB; ++j) {
                                scalar_t wv = cs_weight[j * kvol + wbase + kx];
                                #pragma unroll
                                for (int i = 0; i < WBF; ++i) {
                                    sum[i][j] += a[i] * wv;
                                }
                            }
                        }
                    }
                }
            } else {
                for (int kz = 0; kz < k_d; ++kz) {
                    int t_d = d + p_d - kz;
                    if (t_d % s_d != 0) continue;
                    int ld = t_d / s_d - di0;
                    if (ld < 0 || ld >= ID) continue;
                    for (int ky = 0; ky < k_h; ++ky) {
                        int t_h = h + p_h - ky;
                        if (t_h % s_h != 0) continue;
                        int lh = t_h / s_h - hi0;
                        if (lh < 0 || lh >= IH) continue;
                        int base = (ld * IH + lh) * IWP;
                        int wbase = (kz * k_h + ky) * k_w;
                        for (int kx = 0; kx < k_w; ++kx) {
                            scalar_t a[WBF];
                            int t_w = w + p_w - kx;
                            #pragma unroll
                            for (int i = 0; i < WBF; ++i) {
                                a[i] = (scalar_t)0;
                                int t_wi = t_w + i * TWS;
                                if (valid[i] && (t_wi % s_w) == 0) {
                                    int lwi = t_wi / s_w - wi0;
                                    if (lwi >= 0 && lwi < IW) {
                                        a[i] = cs_in[base + lwi];
                                    }
                                }
                            }
                            #pragma unroll
                            for (int j = 0; j < OCB; ++j) {
                                scalar_t wv = cs_weight[j * kvol + wbase + kx];
                                #pragma unroll
                                for (int i = 0; i < WBF; ++i) {
                                    sum[i][j] += a[i] * wv;
                                }
                            }
                        }
                    }
                }
            }
        }
        buf ^= 1;
        __syncthreads();
    }
    long long oc_stride = (long long)out_d * out_h * out_w;
    #pragma unroll
    for (int i = 0; i < WBF; ++i) {
        if (valid[i]) {
            long long out_base = ((((long long)n * out_channels + oc0) * out_d + d) * out_h + h) * out_w + w + i * TWS;
            #pragma unroll
            for (int j = 0; j < OCB; ++j) {
                if (j < oc_count) output[out_base + (long long)j * oc_stride] = sum[i][j];
            }
        }
    }
}
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    std::vector<int64_t> stride,
    std::vector<int64_t> padding,
    std::vector<int64_t> output_padding,
    int64_t groups)
{
    TORCH_CHECK(input.is_cuda(), "input must be CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA tensor");
    TORCH_CHECK(input.dim() == 5, "input must be 5D (N, C, D, H, W)");
    auto input_c = input.contiguous();
    auto weight_c = weight.contiguous();
    int batch = input_c.size(0);
    int in_channels = input_c.size(1);
    int in_d = input_c.size(2);
    int in_h = input_c.size(3);
    int in_w = input_c.size(4);
    int out_channels = weight_c.size(1) * groups;
    int k_d = weight_c.size(2);
    int k_h = weight_c.size(3);
    int k_w = weight_c.size(4);
    int out_d = (in_d - 1) * stride[0] - 2 * padding[0] + k_d + output_padding[0];
    int out_h = (in_h - 1) * stride[1] - 2 * padding[1] + k_h + output_padding[1];
    int out_w = (in_w - 1) * stride[2] - 2 * padding[2] + k_w + output_padding[2];
    auto output = torch::empty({batch, out_channels, out_d, out_h, out_w}, input_c.options());
    bool has_bias = bias.has_value() && bias->defined();
    torch::Tensor bias_c;
    if (has_bias) bias_c = bias->contiguous();
    long long total = (long long)batch * out_channels * out_d * out_h * out_w;
    if (total == 0) return output;
    const int TD = 4, TH = 8, TW = 32, TWS = 8;
    int tiles_d = (out_d + TD - 1) / TD;
    int tiles_h = (out_h + TH - 1) / TH;
    int tiles_w = (out_w + TW - 1) / TW;
    long long tiles_total = (long long)batch * tiles_d * tiles_h * tiles_w;
    int ID_max = (TD + k_d - 2) / (int)stride[0] + 2;
    int IH_max = (TH + k_h - 2) / (int)stride[1] + 2;
    int IW_max = (TW + k_w - 2) / (int)stride[2] + 2;
    int oc_per_group = (int)(out_channels / groups);
    int ocb = 1;
    if (oc_per_group >= 8) ocb = 8;
    else if (oc_per_group >= 4) ocb = 4;
    else if (oc_per_group >= 2) ocb = 2;
    int chunks_per_group = (oc_per_group + ocb - 1) / ocb;
    long long smem_elems = 2LL * ((long long)ID_max * IH_max * (IW_max + 1) + (long long)ocb * k_d * k_h * k_w);
    size_t smem_bytes = (size_t)smem_elems * input_c.element_size();
    int threads = TD * TH * TWS;
    dim3 grid((unsigned int)tiles_total, (unsigned int)((long long)groups * chunks_per_group), 1);
#define CONV3D_LAUNCH(OCB_VAL) \
    do { \
        cudaFuncSetAttribute(conv_transpose3d_kernel<scalar_t, OCB_VAL>, \
                             cudaFuncAttributePreferredSharedMemoryCarveout, \
                             (int)cudaSharedmemCarveoutMaxShared); \
        if (smem_bytes > 48 * 1024) { \
            cudaFuncSetAttribute(conv_transpose3d_kernel<scalar_t, OCB_VAL>, \
                                 cudaFuncAttributeMaxDynamicSharedMemorySize, \
                                 (int)smem_bytes); \
        } \
        conv_transpose3d_kernel<scalar_t, OCB_VAL><<<grid, threads, smem_bytes>>>( \
            input_c.data_ptr<scalar_t>(), \
            weight_c.data_ptr<scalar_t>(), \
            has_bias ? bias_c.data_ptr<scalar_t>() : nullptr, \
            output.data_ptr<scalar_t>(), \
            batch, in_channels, out_channels, \
            in_d, in_h, in_w, \
            out_d, out_h, out_w, \
            k_d, k_h, k_w, \
            (int)stride[0], (int)stride[1], (int)stride[2], \
            (int)padding[0], (int)padding[1], (int)padding[2], \
            (int)groups, has_bias, \
            tiles_d, tiles_h, tiles_w); \
    } while (0)
    AT_DISPATCH_FLOATING_TYPES(input_c.scalar_type(), "conv_transpose3d_cuda", ([&] {
        switch (ocb) {
            case 8: CONV3D_LAUNCH(8); break;
            case 4: CONV3D_LAUNCH(4); break;
            case 2: CONV3D_LAUNCH(2); break;
            default: CONV3D_LAUNCH(1); break;
        }
    }));
#undef CONV3D_LAUNCH
    return output;
}
"""
cpp_src = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    std::vector<int64_t> stride,
    std::vector<int64_t> padding,
    std::vector<int64_t> output_padding,
    int64_t groups);
"""
_conv_transpose3d_ext = load_inline(
    name="conv_transpose3d_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["conv_transpose3d_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)
class ModelNew(nn.Module):
    """
    ConvTranspose3d implemented with a single custom CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0),
                 output_padding: tuple = (0, 0, 0), groups: int = 1,
                 bias: bool = False):
        super(ModelNew, self).__init__()
        assert in_channels % groups == 0
        assert out_channels % groups == 0
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = tuple(kernel_size)
        self.stride = tuple(stride)
        self.padding = tuple(padding)
        self.output_padding = tuple(output_padding)
        self.groups = groups
        self.weight = nn.Parameter(
            torch.empty(in_channels, out_channels // groups, *self.kernel_size)
        )
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)
        self.reset_parameters()
    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size[0] * self.kernel_size[1] * self.kernel_size[2]
            bound = 1.0 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            x = x.cuda()
        weight = self.weight
        bias = self.bias
        if not weight.is_cuda:
            weight = weight.cuda()
        if bias is not None and not bias.is_cuda:
            bias = bias.cuda()
        return _conv_transpose3d_ext.conv_transpose3d_cuda(
            x, weight, bias,
            list(self.stride), list(self.padding),
            list(self.output_padding), self.groups
        )

